import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/reference/troubleshooting.md","filePath":"zh/reference/troubleshooting.md","lastUpdated":1793111003000}'),h={name:"zh/reference/troubleshooting.md"};function o(l,t,i,n,s,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p>先在索引中找到你的症状，对照可能原因，再按链接处理。先看可见的任务状态和错误信息：上游缓慢、任务排队和浏览器断线需要不同的处理方式。</p><h2 id="症状索引" tabindex="-1">症状索引 <a class="header-anchor" href="#症状索引" aria-label="Permalink to &quot;症状索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>可能原因</th><th>前往</th></tr></thead><tbody><tr><td>检索耗时很长</td><td>任务排队、预算较大或上游阶段缓慢</td><td><a href="#检索耗时很长">检索问题</a></td></tr><tr><td>HTTP 401 / 403</td><td>密钥错误或服务商账户权限不足</td><td><a href="#http-401、403、404-或-429">HTTP 错误</a></td></tr><tr><td>HTTP 404</td><td>基础地址、协议、路由或模型错误</td><td><a href="#http-401、403、404-或-429">HTTP 错误</a></td></tr><tr><td>HTTP 429</td><td>服务商速率限制或余额不足</td><td><a href="#http-401、403、404-或-429">HTTP 错误</a></td></tr><tr><td>连接失败 / 超时</td><td>网络可达性或服务商可用性</td><td><a href="#http-401、403、404-或-429">HTTP 错误</a></td></tr><tr><td>在线版拒绝了接口地址</td><td>非公开地址（localhost、内网）</td><td><a href="#在线版拒绝了模型地址">在线版拒绝了模型地址</a></td></tr><tr><td>没有结果、缺摘要或数量不一致</td><td>查询限制过严或来源记录有缺口</td><td><a href="#没有结果、缺摘要或数量不一致">没有结果</a></td></tr><tr><td>引用图谱为空</td><td>数据源不支持扩展，或预算内没有可用链接</td><td><a href="#引用图谱为空">引用图谱为空</a></td></tr><tr><td>综述大纲或正文失败</td><td>模型可用性或服务商错误</td><td><a href="#综述大纲或正文生成失败">综述大纲或正文生成失败</a></td></tr><tr><td>按主题自动挑选没有可用结果</td><td>写作模型返回的列表无效或无法连接</td><td><a href="#按主题自动挑选没有得到可用结果">按主题自动挑选没有得到可用结果</a></td></tr><tr><td>本地服务无法启动</td><td>Python 版本、数据库路径或端口冲突</td><td><a href="#本地服务无法启动">本地服务无法启动</a></td></tr><tr><td>登录或邮件验证码问题</td><td>垃圾邮件、验证码过期或已被替换</td><td><a href="./../online/account#收不到邮件或密码操作失败">账户与登录</a></td></tr></tbody></table><h2 id="检索问题" tabindex="-1">检索问题 <a class="header-anchor" href="#检索问题" aria-label="Permalink to &quot;检索问题&quot;">​</a></h2><h3 id="检索耗时很长" tabindex="-1">检索耗时很长 <a class="header-anchor" href="#检索耗时很长" aria-label="Permalink to &quot;检索耗时很长&quot;">​</a></h3><p>先区分<strong>排队中</strong>与<strong>执行中</strong>。默认最多同时运行 4 个任务，其余排队等待（见<a href="./configuration#并发任务">并发任务</a>）。执行期间，检索式改写、数据源请求、引用扩展和模型评分都可能耗时。更大预算允许更多工作，但不保证得到更多有用结果。</p><p>页面断线时，先重新打开已保存的运行查看状态，再决定是否重新提交。在线匿名检索的结果是临时的，见<a href="./../online/privacy#不登录检索">数据与隐私</a>。</p><h3 id="没有结果、缺摘要或数量不一致" tabindex="-1">没有结果、缺摘要或数量不一致 <a class="header-anchor" href="#没有结果、缺摘要或数量不一致" aria-label="Permalink to &quot;没有结果、缺摘要或数量不一致&quot;">​</a></h3><p>放宽问题、去掉过严的领域限制，或换用更合适的数据源。数据源命中数量不等于已下载数量，已下载的候选也不等于最终排序结果。</p><p>摘要、引用数或 PDF 缺失可能来自来源记录本身。PaperSeek 不会从其他来源独立补全缺失的摘要。</p><h3 id="引用图谱为空" tabindex="-1">引用图谱为空 <a class="header-anchor" href="#引用图谱为空" aria-label="Permalink to &quot;引用图谱为空&quot;">​</a></h3><p>确认运行使用了支持引用扩展的数据源，并且启用了扩展。即便如此，来源也可能在当前预算内没有提供可用引用关系。</p><h2 id="http-与服务商错误" tabindex="-1">HTTP 与服务商错误 <a class="header-anchor" href="#http-与服务商错误" aria-label="Permalink to &quot;HTTP 与服务商错误&quot;">​</a></h2><h3 id="http-401、403、404-或-429" tabindex="-1">HTTP 401、403、404 或 429 <a class="header-anchor" href="#http-401、403、404-或-429" aria-label="Permalink to &quot;HTTP 401、403、404 或 429&quot;">​</a></h3><table tabindex="0"><thead><tr><th>错误</th><th>检查</th></tr></thead><tbody><tr><td>401 / 403</td><td>密钥是否正确、服务商账户权限、所选模型</td></tr><tr><td>404</td><td>API 基础地址、协议、路由、模型可用性，或任务/资源是否存在</td></tr><tr><td>429</td><td>服务商速率限制，或结构化的余额不足错误</td></tr><tr><td>连接失败 / 超时</td><td>网络可达性与服务商可用性；如果所在网络无法访问该服务，可设置<a href="./configuration#网络代理">网络代理</a></td></tr></tbody></table><p>OpenAlex 运行中显示的 404，并不证明一定是 OpenAlex 返回的：任务中还会调用模型和应用接口。请记录阶段、安全错误码、任务 ID 和时间。</p><p>PaperSeek 服务的积分与上游服务商的余额是两套限制，增加其中一个不会改变另一个。</p><h3 id="在线版拒绝了模型地址" tabindex="-1">在线版拒绝了模型地址 <a class="header-anchor" href="#在线版拒绝了模型地址" aria-label="Permalink to &quot;在线版拒绝了模型地址&quot;">​</a></h3><p>在线版自带密钥模式会拦截 localhost、内网地址等非公开目标。请使用公开的服务商接口地址，或在社区版中连接自己电脑上的模型。地址有效之外，还必须实现所选的 API 协议。</p><h2 id="综述问题" tabindex="-1">综述问题 <a class="header-anchor" href="#综述问题" aria-label="Permalink to &quot;综述问题&quot;">​</a></h2><h3 id="综述大纲或正文生成失败" tabindex="-1">综述大纲或正文生成失败 <a class="header-anchor" href="#综述大纲或正文生成失败" aria-label="Permalink to &quot;综述大纲或正文生成失败&quot;">​</a></h3><p>综述写作是实验性功能，取决于选中的证据和模型可用性。优先选择摘要完整的文献，查看当前项目/任务状态，解决报告的服务商问题后再重试失败环节。避免反复创建重复项目。</p><p>更长的正文需要模型输出更多内容。大纲完成不代表下一次写作请求一定成功。重新生成前保留手工修改并检查版本。</p><p>某一节失败时，其他章节仍会写完并保存。重试只会重写缺失或需要修订的章节。</p><h3 id="按主题自动挑选没有得到可用结果" tabindex="-1">按主题自动挑选没有得到可用结果 <a class="header-anchor" href="#按主题自动挑选没有得到可用结果" aria-label="Permalink to &quot;按主题自动挑选没有得到可用结果&quot;">​</a></h3><p>写作模型没有返回有效列表，或无法连接。检查写作设置中的写作模型后重试，也可以手动勾选文献。自动挑选只给出建议，生成大纲之前不会创建任何内容。</p><h2 id="本地服务" tabindex="-1">本地服务 <a class="header-anchor" href="#本地服务" aria-label="Permalink to &quot;本地服务&quot;">​</a></h2><h3 id="本地服务无法启动" tabindex="-1">本地服务无法启动 <a class="header-anchor" href="#本地服务无法启动" aria-label="Permalink to &quot;本地服务无法启动&quot;">​</a></h3><p>执行 <code>paperseek doctor --json</code>。检查 Python 3.12+、所选数据库路径、写权限、端口冲突和模型设置。执行日志请在启动终端或服务管理器中查看；Web 界面刻意聚焦状态，不显示原始执行日志。</p><p>分开运行时，确认 API 和 worker 使用同一个数据库。</p><h2 id="反馈可复现的问题" tabindex="-1">反馈可复现的问题 <a class="header-anchor" href="#反馈可复现的问题" aria-label="Permalink to &quot;反馈可复现的问题&quot;">​</a></h2><p>在 <a href="https://github.com/paperseek/paperseek/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 提交：</p><ul><li>安装版本或在线模式、浏览器及系统、复现步骤。</li><li>数据源、协议、排序方式和预算。</li><li>期望行为、实际错误、适当的任务 ID 和大致时间。</li><li>不含敏感信息的最小示例，必要时附裁剪后的截图。</li></ul><p>删除 API 密钥、密码、验证码、Cookie、私人检索问题和身份信息。安全问题请走仓库的<a href="https://github.com/paperseek/paperseek/blob/main/SECURITY.md" target="_blank" rel="noreferrer">安全反馈流程</a>。</p>',35)])])}const u=a(h,[["render",o]]);export{b as __pageData,u as default};
